public class SecurityEventMiddleware
{
    private readonly RequestDelegate _next;

    public SecurityEventMiddleware(RequestDelegate next) => _next = next;

    public async Task InvokeAsync(HttpContext context)
    {
        await _next(context);

        if (context.Response.StatusCode == 401 || context.Response.StatusCode == 403)
        {
            Log.Warning("Security event: {StatusCode} for {Path}",
                context.Response.StatusCode, context.Request.Path);
        }

        if (context.Response.StatusCode == 429)
        {
            Log.Warning("Rate limit hit for {Ip}", context.Connection.RemoteIpAddress);
        }
    }
}
